use genex::prelude::*;

/// Breath on a cold day: a few small puffs, started well in front of the lens and drifting away from it.
fn breath(eye: Vec3, forward: Vec3) -> Particles {
    Particles::steam(eye + forward * 0.6 - vec3(0.0, 0.12, 0.0))
        .with_rate(1, 50)
        .with_motion(forward * 0.01, 0.004, -0.0001)
        .with_look(0.05, 2.5, Color::rgba(235, 240, 245, 70), Color::rgba(235, 240, 245, 0))
        .with_sorted(true)
}

fn draw_breath(w: &super::World, frame: &mut Frame) {
    if w.breathing { frame.tag("breath").particles(&w.breath); } // rebuilt in on_update from the player's eye
}
